    message = message.replace(" ", "").upper()

    if len(encoded) != len(original) or len(encoded) != len(message):
        return "Failed"

    # build a mapping from encoded letters to original
    encoded_to_original = {}

    # find contradiction during mapping construction
    for i in range(len(encoded)):
        if encoded[i] in encoded_to_original:
            if encoded_to_original[encoded[i]] != original[i]:
                return "Failed"
        elif not encoded[i] in encoded_to_original:
            encoded_to_original[encoded[i]] = original[i]

    if len(encoded_to_original) != len(set(original)):
        return "Failed"

    # decode the given message
    decoded = ""
    for char in message:
        if char in encoded_to_original:
            decoded += encoded_to_original[char]
        else:
            # skip unsupported characters
            continue

    return decoded

