def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    @lru_cache(None)
    def dfs(index: int, time: int) -> int:
        if index == M:
            return 0 if time <= T else -float('inf')

        # Skip the current herb
        skip = dfs(index + 1, time)

        # Pick the current herb
        pick = herb[1] + dfs(index + 1, time + herb[0])

        return max(skip, pick)

    return dfs(0, 0)

