def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [float('-inf')] * (V + 1)
    dp[0] = 0  # Base case: no volume can fit with enough space

    for i in range(n):
        for w in range(V, volumes[i]-1, -1):
            dp[w] = max(dp[w], dp[w - volumes[i]] + volumes[i])

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - dp[V]

